import type { SearchResult } from "../indexer/index.js";

import { get_encoding } from "tiktoken";
import * as path from "node:path";

import { isLikelyImplementationPath } from "../indexer/intent-aware-ranking.js";
import { canonicalizePathForComparison } from "../utils/canonical-path.js";

export const MIN_CONTEXT_PACK_TOKEN_BUDGET = 128;
export const MAX_CONTEXT_PACK_TOKEN_BUDGET = 4000;
export const DEFAULT_CONTEXT_PACK_TOKEN_BUDGET = 1200;
const CONTEXT_TOKENIZER = get_encoding("cl100k_base");
const CONTEXT_ORIGIN_DIVERSITY_SCORE_RATIO = 0.8;

interface RankedSearchResult {
  result: SearchResult;
  originalIndex: number;
}

export interface ContextPackOptions {
  origins?: Array<{ root: string; label: string }>;
  tokenBudget?: number;
  heading?: string;
  maxResults?: number;
  includeExactSearchHandoff?: boolean;
  preferImplementationPaths?: boolean;
  projectRoot?: string;
  preserveInputOrder?: boolean;
  trace?: (trace: ContextPackTrace) => void;
  /** Complete rendered rows, with UTF-16 end offsets into the packed text. */
  onSelectedEvidence?: (evidence: Array<{ result: SearchResult; endOffset: number }>) => void;
}

interface CanonicalContextOrigin {
  root: string;
  label: string;
}

export interface ContextPackTrace {
  inputCandidates: Array<{
    filePath: string;
    startLine: number;
    endLine: number;
    score: number;
    chunkType: string;
    name?: string;
  }>;
  rankedCandidates: Array<{
    filePath: string;
    startLine: number;
    endLine: number;
    score: number;
    chunkType: string;
    name?: string;
  }>;
  deduplicatedCandidates: Array<{
    filePath: string;
    startLine: number;
    endLine: number;
    score: number;
    chunkType: string;
    name?: string;
  }>;
  diversifiedCandidates: Array<{
    filePath: string;
    startLine: number;
    endLine: number;
    score: number;
    chunkType: string;
    name?: string;
  }>;
  selectedCandidates: Array<{
    filePath: string;
    startLine: number;
    endLine: number;
    score: number;
    chunkType: string;
    name?: string;
  }>;
}

export interface ContextPackResult {
  requestedTokenBudget: number;
  tokenBudget: number;
  text: string;
  tokenEstimate: number;
  results: SearchResult[];
  candidateCount: number;
  deduplicatedCount: number;
  selectedCount: number;
  omittedCount: number;
  duplicateCount: number;
  limitOmittedCount: number;
  budgetOmittedCount: number;
}

export interface BudgetedTextResult {
  text: string;
  tokenBudget: number;
  tokenEstimate: number;
  truncated: boolean;
  /** UTF-16 length of the retained input prefix, excluding the truncation notice. */
  retainedLength: number;
}

export function clampContextPackTokenBudget(tokenBudget?: number): number {
  if (tokenBudget === undefined || !Number.isFinite(tokenBudget)) {
    return DEFAULT_CONTEXT_PACK_TOKEN_BUDGET;
  }
  return Math.min(
    MAX_CONTEXT_PACK_TOKEN_BUDGET,
    Math.max(MIN_CONTEXT_PACK_TOKEN_BUDGET, Math.floor(tokenBudget)),
  );
}

export function countContextTokens(text: string): number {
  return CONTEXT_TOKENIZER.encode(text).length;
}

export function fitTextToContextBudget(text: string, tokenBudget?: number): BudgetedTextResult {
  const normalizedBudget = clampContextPackTokenBudget(tokenBudget);
  const tokenEstimate = countContextTokens(text);
  if (tokenEstimate <= normalizedBudget) {
    return {
      text,
      tokenBudget: normalizedBudget,
      tokenEstimate,
      truncated: false,
      retainedLength: text.length,
    };
  }

  const suffix = "\n...[truncated to context token budget]";
  const codePoints = Array.from(text);
  let low = 0;
  let high = codePoints.length;
  while (low < high) {
    const middle = Math.ceil((low + high) / 2);
    const candidate = `${codePoints.slice(0, middle).join("").trimEnd()}${suffix}`;
    if (countContextTokens(candidate) <= normalizedBudget) low = middle;
    else high = middle - 1;
  }
  const retained = codePoints.slice(0, low).join("").trimEnd();
  const fitted = `${retained}${suffix}`;
  return {
    text: fitted,
    tokenBudget: normalizedBudget,
    tokenEstimate: countContextTokens(fitted),
    truncated: true,
    retainedLength: retained.length,
  };
}

function normalizedLineRange(result: SearchResult): { start: number; end: number } {
  return result.startLine <= result.endLine
    ? { start: result.startLine, end: result.endLine }
    : { start: result.endLine, end: result.startLine };
}

function rankContextCandidates(
  results: SearchResult[],
  preferImplementationPaths: boolean,
  projectRoot: string | undefined,
): RankedSearchResult[] {
  return results
    .map((result, originalIndex) => ({
      result,
      originalIndex,
      isImplementation: preferImplementationPaths && isLikelyImplementationPath(
        projectRoot && path.isAbsolute(result.filePath)
          ? path.relative(projectRoot, result.filePath)
          : result.filePath,
      ),
    }))
    .sort((left, right) => {
      if (left.isImplementation !== right.isImplementation) {
        return left.isImplementation ? -1 : 1;
      }
      return right.result.score - left.result.score || left.originalIndex - right.originalIndex;
    });
}

function deduplicateContextCandidates(candidates: RankedSearchResult[]): SearchResult[] {
  const acceptedByFile = new Map<string, Array<{ start: number; end: number }>>();
  const deduplicated: SearchResult[] = [];

  for (const { result } of candidates) {
    const range = normalizedLineRange(result);
    const locationKey = result.documentLocation?.kind === "pdf"
      ? `${result.filePath}#pdf-page-${result.documentLocation.pageStart}-${result.documentLocation.pageEnd}`
      : result.filePath;
    const accepted = acceptedByFile.get(locationKey) ?? [];
    if (accepted.some((item) => item.start <= range.end && range.start <= item.end)) {
      continue;
    }
    accepted.push(range);
    acceptedByFile.set(locationKey, accepted);
    deduplicated.push(result);
  }

  return deduplicated;
}

function diversifyContextCandidates(results: SearchResult[]): SearchResult[] {
  if (results.length <= 1) return results;
  // File diversity breaks leading relevance ties; it must not demote a stronger declaration.
  const minimumScore = results[0].score;
  let headCount = results.length;
  for (let index = 1; index < results.length; index += 1) {
    if (results[index].score < minimumScore) {
      headCount = index;
      break;
    }
  }

  const byFile = new Map<string, SearchResult[]>();
  for (let index = 0; index < headCount; index += 1) {
    const result = results[index];
    const bucket = byFile.get(result.filePath) ?? [];
    bucket.push(result);
    byFile.set(result.filePath, bucket);
  }

  const files = [...byFile.keys()];
  const diversified: SearchResult[] = [];
  for (let depth = 0; diversified.length < headCount; depth += 1) {
    for (const file of files) {
      const result = byFile.get(file)?.[depth];
      if (result) diversified.push(result);
    }
  }
  for (let index = headCount; index < results.length; index += 1) {
    diversified.push(results[index]);
  }
  return diversified;
}

function canonicalContextPath(targetPath: string): string {
  try {
    return canonicalizePathForComparison(targetPath);
  } catch {
    return path.resolve(targetPath);
  }
}

function canonicalOrigins(origins: NonNullable<ContextPackOptions["origins"]>): CanonicalContextOrigin[] {
  return origins.map((origin) => ({ ...origin, root: canonicalContextPath(origin.root) }));
}

function resultOrigin(result: SearchResult, origins: CanonicalContextOrigin[]): number {
  if (!path.isAbsolute(result.filePath)) return -1;
  const filePath = canonicalContextPath(result.filePath);
  let matched = -1;
  for (let index = 0; index < origins.length; index += 1) {
    const root = origins[index].root;
    if (!path.isAbsolute(root)) continue;
    const relative = path.relative(root, filePath);
    if (relative === ".." || relative.startsWith(`..${path.sep}`) || path.isAbsolute(relative)) continue;
    if (matched < 0 || root.length > origins[matched].root.length) matched = index;
  }
  return matched;
}

function diversifyByOrigin(results: SearchResult[], origins: CanonicalContextOrigin[]): SearchResult[] {
  const fileDiversified = diversifyContextCandidates(results);
  if (origins.length < 2 || fileDiversified.length === 0) return fileDiversified;
  const seen = new Set<number>();
  const first: SearchResult[] = [fileDiversified[0]];
  const topScore = fileDiversified[0].score;
  seen.add(resultOrigin(fileDiversified[0], origins));
  for (const result of fileDiversified.slice(1)) {
    const origin = resultOrigin(result, origins);
    if (origin >= 0 && !seen.has(origin) && topScore > 0 && result.score > 0 && result.score >= topScore * CONTEXT_ORIGIN_DIVERSITY_SCORE_RATIO) {
      seen.add(origin);
      first.push(result);
    }
  }
  const promoted = new Set(first);
  return [...first, ...fileDiversified.filter((result) => !promoted.has(result))];
}

function compactEvidenceValue(value: string, maxChars: number): string {
  const characters = [...value];
  if (characters.length <= maxChars) return value;
  return `…${characters.slice(-(maxChars - 1)).join("")}`;
}

function sanitizeEvidenceDisplayValue(value: string): string {
  const escapeCharacter = String.fromCharCode(0x1b);
  const ansiPattern = new RegExp(`${escapeCharacter}(?:\\[[0-?]*[ -/]*[@-~]|\\][^${String.fromCharCode(0x07)}]*(?:${String.fromCharCode(0x07)}|${escapeCharacter}\\\\))`, "g");
  const controlPattern = new RegExp(`[${String.fromCharCode(0)}-${String.fromCharCode(0x1f)}${String.fromCharCode(0x7f)}-${String.fromCharCode(0x9f)}]`, "g");
  return value
    .replace(ansiPattern, "")
    .replace(controlPattern, (character) => {
      const code = character.codePointAt(0)?.toString(16).padStart(2, "0") ?? "00";
      return `\\x${code}`;
    });
}

const MAX_EXACT_SEARCH_HANDOFF_NAMES = 3;
const MAX_EXACT_SEARCH_HANDOFF_NAME_CHARS = 64;

function toContextPackTraceCandidate(result: SearchResult): ContextPackTrace["inputCandidates"][number] {
  return {
    filePath: result.filePath,
    startLine: result.startLine,
    endLine: result.endLine,
    score: result.score,
    chunkType: result.chunkType,
    name: result.name,
  };
}

export function formatExactSearchHandoff(results: SearchResult[]): string | null {
  const suggestedNames: string[] = [];
  const seen = new Set<string>();

  for (const result of results) {
    const rawName = result.name?.trim();
    if (!rawName) {
      continue;
    }

    if (Array.from(rawName).length > MAX_EXACT_SEARCH_HANDOFF_NAME_CHARS) {
      continue;
    }

    if (seen.has(rawName)) {
      continue;
    }

    seen.add(rawName);
    suggestedNames.push(rawName);

    if (suggestedNames.length >= MAX_EXACT_SEARCH_HANDOFF_NAMES) {
      break;
    }
  }

  if (suggestedNames.length === 0) {
    return null;
  }

  const quotedNames = suggestedNames.map((name) => JSON.stringify(name)).join(", ");
  return `Exact-search handoff: use exact grep/search for ${quotedNames} to find usages or exhaustive matches.`;
}

function formatContextEvidence(result: SearchResult, index: number, origins?: CanonicalContextOrigin[]): string {
  const symbol = result.name ? ` ${JSON.stringify(sanitizeEvidenceDisplayValue(compactEvidenceValue(result.name, 80)))}` : "";
  const origin = origins ? resultOrigin(result, origins) : -1;
  const sourcePath = sanitizeEvidenceDisplayValue(origin >= 0 && origins
    ? path.relative(origins[origin].root, canonicalContextPath(result.filePath))
    : compactEvidenceValue(result.filePath, 120));
  const location = result.documentLocation?.kind === "pdf"
    ? `${sourcePath}, ${result.documentLocation.pageStart === result.documentLocation.pageEnd ? `p. ${result.documentLocation.pageStart}` : `pp. ${result.documentLocation.pageStart}-${result.documentLocation.pageEnd}`}`
    : `${sourcePath}:${result.startLine}-${result.endLine}`;
  const label = origin < 0 || origins?.length === 1 ? "" : ` [origin: ${sanitizeEvidenceDisplayValue(origins?.[origin].label ?? "")}]`;
  return `[${index}] ${result.chunkType}${symbol} in ${location}${label} (score ${result.score.toFixed(2)})`;
}

function formatContextPack(
  heading: string,
  selected: SearchResult[],
  candidateCount: number,
  duplicateCount: number,
  limitOmittedCount: number,
  budgetOmittedCount: number,
  includeExactSearchHandoff: boolean,
  origins?: CanonicalContextOrigin[],
  evidence?: Array<{ result: SearchResult; endOffset: number }>,
): string {
  let offset = heading.length + 2;
  const lines = selected.map((result, index) => {
    const line = formatContextEvidence(result, index + 1, origins);
    if (evidence) {
      offset += line.length;
      evidence.push({ result, endOffset: offset });
      offset += 1;
    }
    return line;
  });
  const notes: string[] = [];
  if (duplicateCount > 0) notes.push(`${duplicateCount} overlapping duplicate${duplicateCount === 1 ? "" : "s"} removed`);
  if (limitOmittedCount > 0) notes.push(`${limitOmittedCount} additional result${limitOmittedCount === 1 ? "" : "s"} excluded by result limit`);
  if (budgetOmittedCount > 0) notes.push(`${budgetOmittedCount} additional result${budgetOmittedCount === 1 ? "" : "s"} omitted by token budget`);
  const footer = notes.length > 0
    ? `Selected ${selected.length} of ${candidateCount} candidates; ${notes.join("; ")}.`
    : `Selected ${selected.length} of ${candidateCount} candidates.`;
  const handoff = includeExactSearchHandoff ? formatExactSearchHandoff(selected) : null;
  return [heading, lines.join("\n"), footer, handoff].filter(Boolean).join("\n\n");
}

export function buildContextPack(results: SearchResult[], options: ContextPackOptions = {}): ContextPackResult {
  const requestedTokenBudget = options.tokenBudget ?? DEFAULT_CONTEXT_PACK_TOKEN_BUDGET;
  const tokenBudget = clampContextPackTokenBudget(options.tokenBudget);
  const heading = compactEvidenceValue(options.heading?.trim() || "Codebase evidence", 160);
  const maxResults = Math.max(0, Math.floor(options.maxResults ?? results.length));
  const includeExactSearchHandoff = options.includeExactSearchHandoff ?? false;
  const candidateCount = results.length;
  const preserveInputOrder = options.preserveInputOrder ?? false;
  const ranked = preserveInputOrder
    ? results.map((result, originalIndex) => ({ result, originalIndex }))
    : rankContextCandidates(results, options.preferImplementationPaths ?? false, options.projectRoot);
  const rankedCandidates = ranked.map((entry) => toContextPackTraceCandidate(entry.result));
  const deduplicated = deduplicateContextCandidates(ranked);
  const deduplicatedCandidates = deduplicated.map((result) => toContextPackTraceCandidate(result));
  const configuredOrigins = options.origins ? canonicalOrigins(options.origins) : [];
  const observedOrigins = new Set(deduplicated.map((result) => resultOrigin(result, configuredOrigins)));
  observedOrigins.delete(-1);
  const origins = !preserveInputOrder && configuredOrigins.length > 0 ? configuredOrigins : undefined;
  const diversified = preserveInputOrder ? deduplicated : origins && observedOrigins.size > 1
    ? diversifyByOrigin(deduplicated, origins)
    : diversifyContextCandidates(deduplicated);
  const diversifiedCandidates = diversified.map((result) => toContextPackTraceCandidate(result));
  const duplicateCount = candidateCount - deduplicated.length;
  const selectable = diversified.slice(0, maxResults);
  const limitOmittedCount = deduplicated.length - selectable.length;
  let selected: SearchResult[] = [];
  let selectedEvidence: Array<{ result: SearchResult; endOffset: number }> | undefined;
  let text = formatContextPack(
    heading,
    selected,
    candidateCount,
    duplicateCount,
    limitOmittedCount,
    selectable.length,
    includeExactSearchHandoff,
    origins,
  );

  for (let count = 1; count <= selectable.length; count += 1) {
    const candidateSelection = selectable.slice(0, count);
    const budgetOmittedCount = selectable.length - candidateSelection.length;
    const candidateEvidence: Array<{ result: SearchResult; endOffset: number }> | undefined =
      options.onSelectedEvidence ? [] : undefined;
    const candidateText = formatContextPack(
      heading,
      candidateSelection,
      candidateCount,
      duplicateCount,
      limitOmittedCount,
      budgetOmittedCount,
      includeExactSearchHandoff,
      origins,
      candidateEvidence,
    );
    if (countContextTokens(candidateText) > tokenBudget) break;
    selected = candidateSelection;
    text = candidateText;
    if (candidateEvidence) selectedEvidence = candidateEvidence;
  }

  const fitted = fitTextToContextBudget(text, tokenBudget);
  options.onSelectedEvidence?.((selectedEvidence ?? []).filter((entry) => entry.endOffset <= fitted.retainedLength));
  const budgetOmittedCount = selectable.length - selected.length;
  const omittedCount = candidateCount - selected.length;
  if (options.trace) {
    options.trace({
      inputCandidates: results.map(toContextPackTraceCandidate),
      rankedCandidates,
      deduplicatedCandidates,
      diversifiedCandidates,
      selectedCandidates: selected.map(toContextPackTraceCandidate),
    });
  }
  return {
    requestedTokenBudget,
    tokenBudget,
    text: fitted.text,
    tokenEstimate: fitted.tokenEstimate,
    results: selected,
    candidateCount,
    deduplicatedCount: deduplicated.length,
    selectedCount: selected.length,
    omittedCount,
    duplicateCount,
    limitOmittedCount,
    budgetOmittedCount,
  };
}
